<?php declare(strict_types=1);?><section class="section"><div class="container-narrow"><div class="section-heading"><p class="eyebrow">Member portal</p><h1>My certificates</h1><p>Issued certificate records associated with your authenticated membership.</p></div><div class="admin-list"><?php if($certificates===[]):?><p>No certificates have been issued to this membership.</p><?php endif;?><?php foreach($certificates as$c):?><article class="admin-panel"><strong><?= $e($c['certificate_number']) ?></strong><p><?= $e($c['certificate_type']) ?> · <?= $e($c['issue_date']) ?></p><span class="status-pill"><?= $e(ucwords($c['status'])) ?></span><?php if($c['programme_name']):?><p><?= $e($c['programme_name']) ?></p><?php endif;?><?php if($c['event_title']):?><p><?= $e($c['event_title']) ?></p><?php endif;?></article><?php endforeach;?></div></div></section>
